public class JoinCostCalculator
{
    private readonly CostEstimator _costEstimator;

    public JoinCostCalculator(CostEstimator costEstimator)
    {
        _costEstimator = costEstimator;
    }

    public double CalculateBestJoinOrder(List<TableReferenceNode> tables)
    {
        if (tables.Count <= 1) return 0;

        // Generate all possible join orders
        var permutations = GeneratePermutations(tables);

        double minCost = double.MaxValue;
        var bestOrder = new List<TableReferenceNode>();

        foreach (var order in permutations)
        {
            double totalCost = 0;
            TableReferenceNode previous = null;

            foreach (var table in order)
            {
                if (previous != null)
                {
                    // Find join condition between previous and current table
                    var joinCondition = FindJoinCondition(previous, table);
                    totalCost += _costEstimator.EstimateJoinCost(
                        new JoinNode { LeftTable = previous, RightTable = table },
                        JoinType.HashJoin);
                }
                totalCost += _costEstimator.EstimateSelectivity(previous.WhereClause);
            }

            if (totalCost < minCost)
            {
                minCost = totalCost;
                bestOrder = order;
            }
        }

        return minCost;
    }

    // Helper methods...
}
