public class PlanGenerator
{
    private readonly CostEstimator _costEstimator;

    public PlanGenerator(CostEstimator costEstimator)
    {
        _costEstimator = costEstimator;
    }

    public PhysicalOperatorTree GeneratePlan(ASTNode ast)
    {
        var plan = new PhysicalOperatorTree();

        // Convert AST to logical operators
        var logicalOperators = ConvertToLogicalOperators(ast);

        // Optimize join order
        var optimizedOperators = OptimizeJoinOrder(logicalOperators);

        // Convert to physical operators
        foreach (var op in optimizedOperators)
        {
            plan.AddOperator(ConvertToPhysicalOperator(op));
        }

        return plan;
    }

    // Helper methods...
}

// PhysicalOperatorTree.cs
public class PhysicalOperatorTree
{
    private readonly List<PhysicalOperator> _operators = new();
    private readonly Dictionary<string, PhysicalOperator> _operatorMap = new();

    public void AddOperator(PhysicalOperator op)
    {
        _operators.Add(op);
        _operatorMap[op.GetType().Name] = op;
    }

    public void Execute(QueryContext context)
    {
        foreach (var op in _operators)
        {
            op.Execute(context);
        }
    }
}
